"""K=5 epsilon sensitivity analysis for log-log OLS regression."""

import sys
import json
import os
import itertools
import numpy as np
import statsmodels.api as sm

sys.path.insert(0, "/root/cert_manip_resist_eval")
from src.unified_data_loader import load_all_scores, load_mi_data, load_pairs, ALL_MODELS, DATASETS, ATTACKS

K = 5
EPSILONS = [1e-3, 1e-6, 1e-9]


def majority_vote(votes):
    counts = {"A": 0, "B": 0, "tie": 0}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    mx = max(counts.values())
    winners = [k for k, c in counts.items() if c == mx]
    if len(winners) == 1:
        return winners[0]
    for w in winners:
        if w != "tie":
            return w
    return "tie"


def compute_individual_asr(clean_list, attacked_list, pairs):
    n = min(len(clean_list), len(attacked_list), len(pairs))
    n_flips = n_correct = 0
    for i in range(n):
        gt = pairs[i]["ground_truth_winner"]
        if clean_list[i].get("winner", "tie") == gt:
            n_correct += 1
            if attacked_list[i].get("winner", "tie") != gt:
                n_flips += 1
    return n_flips / max(n_correct, 1)


def compute_panel_asr(jids, clean, attacked, pairs):
    n = min(len(pairs), *(len(clean[j]) for j in jids), *(len(attacked[j]) for j in jids))
    n_flips = n_correct = 0
    for i in range(n):
        gt = pairs[i]["ground_truth_winner"]
        cv = majority_vote([clean[j][i].get("winner", "tie") for j in jids])
        if cv != gt:
            continue
        n_correct += 1
        av = majority_vote([attacked[j][i].get("winner", "tie") for j in jids])
        if av != gt:
            n_flips += 1
    return n_flips / max(n_correct, 1)


def compute_keff_k5(jids, models, mi_matrix):
    """Compute K_eff = 1 + (K-1)*exp(-2*I_max) for a K=5 panel."""
    idx = {m: i for i, m in enumerate(models)}
    max_mi = 0.0
    for a, b in itertools.combinations(jids, 2):
        mi_val = mi_matrix[idx[a]][idx[b]]
        if mi_val > max_mi:
            max_mi = mi_val
    return 1.0 + (K - 1) * np.exp(-2.0 * max_mi)


def run_ols(p_asrs, p_keffs, p_etas, eps):
    log_asr = np.log(p_asrs + eps)
    log_keff = np.log(p_keffs)
    log_eta = np.log(p_etas + eps)
    X = sm.add_constant(np.column_stack([log_keff, log_eta]))
    result = sm.OLS(log_asr, X).fit()

    sd_y = np.std(log_asr)
    keff_beta_std = float(result.params[1] * np.std(log_keff) / sd_y) if sd_y > 0 else 0.0
    eta_beta_std = float(result.params[2] * np.std(log_eta) / sd_y) if sd_y > 0 else 0.0

    return {
        "keff_beta_std": round(keff_beta_std, 6),
        "eta_beta_std": round(eta_beta_std, 6),
        "keff_p": float(result.pvalues[1]),
        "eta_p": float(result.pvalues[2]),
        "R2": float(result.rsquared),
    }


def main():
    print("Loading data...")
    clean, attacked = load_all_scores()
    pairs_list = load_pairs()
    mi_data = load_mi_data()
    models = mi_data["models"]

    conditions = [(ds, atk) for ds in DATASETS for atk in ATTACKS]

    # Precompute individual ASR per model per condition
    print("Computing individual ASRs...")
    ind_asr = {}
    for ds, atk in conditions:
        ck = f"{ds}_{atk}"
        ind_asr[ck] = {}
        for m in ALL_MODELS:
            if m in clean[ds] and m in attacked[ds].get(atk, {}):
                ind_asr[ck][m] = compute_individual_asr(
                    clean[ds][m], attacked[ds][atk][m], pairs_list[ds]
                )

    # Precompute keff for all K=5 panels (per dataset)
    print(f"Computing K_eff for C(15,5)=3003 panels...")
    all_combos = list(itertools.combinations(ALL_MODELS, K))
    print(f"  Total combos: {len(all_combos)}")

    keff_cache = {}
    for ds in DATASETS:
        mi_mat = mi_data["mi_matrix"][ds]
        keff_cache[ds] = {}
        for combo in all_combos:
            jids = list(combo)
            pk = "|".join(jids)
            keff_cache[ds][pk] = compute_keff_k5(jids, models, mi_mat)

    # Compute panel ASR for all K=5 panels per condition
    print("Computing panel ASRs...")
    panel_data = {}
    for ds, atk in conditions:
        ck = f"{ds}_{atk}"
        p_asrs, p_keffs, p_etas = [], [], []
        for combo in all_combos:
            jids = list(combo)
            pk = "|".join(jids)
            if not all(j in ind_asr[ck] for j in jids):
                continue
            if not all(j in clean[ds] and j in attacked[ds].get(atk, {}) for j in jids):
                continue

            asr = compute_panel_asr(jids, clean[ds], attacked[ds][atk], pairs_list[ds])
            keff = keff_cache[ds][pk]
            eta_max = max(ind_asr[ck][j] for j in jids)

            p_asrs.append(asr)
            p_keffs.append(keff)
            p_etas.append(eta_max)

        panel_data[ck] = (np.array(p_asrs), np.array(p_keffs), np.array(p_etas))
        n_zero = np.sum(np.array(p_asrs) == 0)
        print(f"  {ck}: {len(p_asrs)} panels, {n_zero} zero-ASR ({n_zero/max(len(p_asrs),1)*100:.1f}%)")

    # ASR zero rates
    asr_zero_rates = {}
    for ck, (asrs, _, _) in panel_data.items():
        asr_zero_rates[ck] = round(float(np.mean(asrs == 0)), 4) if len(asrs) > 0 else None

    # Run OLS for each epsilon
    print("\nRunning OLS regressions...")
    coefficients_by_epsilon = {}
    for eps in EPSILONS:
        eps_key = f"{eps:.0e}"
        coefficients_by_epsilon[eps_key] = {}
        for ck, (p_asrs, p_keffs, p_etas) in panel_data.items():
            if len(p_asrs) < 10:
                continue
            result = run_ols(p_asrs, p_keffs, p_etas, eps)
            coefficients_by_epsilon[eps_key][ck] = result
            print(f"  ε={eps_key} {ck}: keff_β={result['keff_beta_std']:.4f}, η_β={result['eta_beta_std']:.4f}, R²={result['R2']:.4f}")

    # Max coefficient change relative to 1e-6 baseline
    baseline_key = "1e-06"
    max_keff_change = 0.0
    max_eta_change = 0.0
    for eps_key in coefficients_by_epsilon:
        if eps_key == baseline_key:
            continue
        for ck in coefficients_by_epsilon[eps_key]:
            if ck not in coefficients_by_epsilon.get(baseline_key, {}):
                continue
            base = coefficients_by_epsilon[baseline_key][ck]
            cur = coefficients_by_epsilon[eps_key][ck]
            if abs(base["keff_beta_std"]) > 1e-10:
                chg = abs((cur["keff_beta_std"] - base["keff_beta_std"]) / base["keff_beta_std"]) * 100
                max_keff_change = max(max_keff_change, chg)
            if abs(base["eta_beta_std"]) > 1e-10:
                chg = abs((cur["eta_beta_std"] - base["eta_beta_std"]) / base["eta_beta_std"]) * 100
                max_eta_change = max(max_eta_change, chg)

    output = {
        "K": K,
        "n_panels": len(all_combos),
        "asr_zero_rates": asr_zero_rates,
        "coefficients_by_epsilon": coefficients_by_epsilon,
        "max_coefficient_change": {
            "keff": round(max_keff_change, 2),
            "eta": round(max_eta_change, 2),
        },
    }

    out_path = "/root/cert_manip_resist_eval/artifacts/results/plan001/epsilon_sensitivity_k5.json"
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nSaved to {out_path}")
    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
